static_cast<T*>(ptr); // OK: Conversion between related types
                      // (e.g., void* to T*). NO runtime check.

int i = 42;
void* vPtr = &i;
int* iPtr = static_cast<int*>(vPtr); // Safe, type-aware pointer cast.

// --- DANGER ZONE (Reinterpreting Memory) ---

char bytes[4];
int* badPtr = reinterpret_cast<int*>(bytes); // DANGER: Alignment/Strict Aliasing violation possible.

// Correct usage of reinterpret_cast (e.g., hash calc or API interop):
uintptr_t addr = reinterpret_cast<uintptr_t>(&i); // Pointer to integer type conversion.
